import fs from "node:fs";
import type { NerEngine, NerItem } from "../ner-engine.js";
import { chunkWindows } from "./chunk.js";
import { buildLabelTable, decodeBioes, type DecodedLabel, type Prediction, type Span } from "./decode.js";
import { dedupeSpans, filterSpans } from "./merge.js";
import { parseVariant, resolveMaskerFiles, type MaskerVariant } from "./model-files.js";
import { tokenizeWithOffsets, type ContentToken, type TokenizerLike } from "./tokenize.js";

const CLS_ID = 1;
const SEP_ID = 2;

export interface MaskerLoadOptions {
  variant?: MaskerVariant;
  directory?: string;
}

/** Minimal views of the onnxruntime-node API we use. */
interface OrtTensorLike {
  dims: readonly number[];
  data: ArrayLike<number | bigint>;
}
interface OrtSessionLike {
  inputNames: readonly string[];
  outputNames: readonly string[];
  run(feeds: Record<string, unknown>): Promise<Record<string, OrtTensorLike>>;
  release(): Promise<void>;
}
interface OrtLike {
  Tensor: new (type: "int64", data: BigInt64Array, dims: number[]) => unknown;
  InferenceSession: {
    create(path: string, options?: Record<string, unknown>): Promise<OrtSessionLike>;
  };
}

async function importOptional<T>(name: string): Promise<T> {
  try {
    const mod = (await import(name)) as { default?: unknown };
    return ((mod as Record<string, unknown>).InferenceSession || !mod.default ? mod : mod.default) as T;
  } catch (error) {
    throw new Error(
      `masker-mini backend needs the optional packages "onnxruntime-node" and "@huggingface/tokenizers" ` +
        `(install them with: npm install onnxruntime-node @huggingface/tokenizers): ${(error as Error).message}`
    );
  }
}

/** Softmax over one row of logits; returns [argmax, probability of argmax]. */
export function argmaxSoftmax(logits: ArrayLike<number | bigint>, offset: number, width: number): [number, number] {
  let max = -Infinity;
  let arg = 0;
  for (let i = 0; i < width; i++) {
    const v = Number(logits[offset + i]);
    if (v > max) {
      max = v;
      arg = i;
    }
  }
  let sum = 0;
  for (let i = 0; i < width; i++) sum += Math.exp(Number(logits[offset + i]) - max);
  return [arg, 1 / sum];
}

export class MaskerMini implements NerEngine {
  private session: OrtSessionLike | null;
  private readonly ort: OrtLike;
  private readonly tokenizer: TokenizerLike;
  private readonly labels: Array<DecodedLabel | null>;

  // No parameter properties: the package ships .ts source, which must stay strip-only compatible.
  private constructor(
    session: OrtSessionLike,
    ort: OrtLike,
    tokenizer: TokenizerLike,
    labels: Array<DecodedLabel | null>
  ) {
    this.session = session;
    this.ort = ort;
    this.tokenizer = tokenizer;
    this.labels = labels;
  }

  static async load(opts: MaskerLoadOptions = {}): Promise<MaskerMini> {
    const files = await resolveMaskerFiles({ variant: opts.variant, directory: opts.directory });
    const ort = await importOptional<OrtLike>("onnxruntime-node");
    const { Tokenizer } = await importOptional<{
      Tokenizer: new (json: unknown, config: unknown) => TokenizerLike;
    }>("@huggingface/tokenizers");
    const readJson = (p: string) => JSON.parse(fs.readFileSync(p, "utf8"));
    const tokenizer = new Tokenizer(readJson(files.tokenizerPath), readJson(files.tokenizerConfigPath));
    const labels = buildLabelTable(readJson(files.configPath).id2label);
    // logSeverityLevel 3 = errors only, so ORT warnings do not land in Pi's TUI.
    const session = await ort.InferenceSession.create(files.modelPath, { logSeverityLevel: 3 });
    return new MaskerMini(session, ort, tokenizer, labels);
  }

  async redaction(
    text: string,
    options: { labels?: Iterable<string>; minimumConfidence?: number } = {}
  ): Promise<{ items: NerItem[] }> {
    const session = this.session;
    if (!session) throw new Error("masker-mini: model has been disposed");
    if (!options.labels || !text.trim()) return { items: [] };

    const tokens = tokenizeWithOffsets(this.tokenizer, text);
    const spans: Span[] = [];
    for (const window of chunkWindows(tokens)) {
      spans.push(...(await this.runWindow(session, window, text)));
    }
    const kept = dedupeSpans(filterSpans(spans, options.labels, options.minimumConfidence ?? 0));
    return {
      items: kept.map((s) => ({
        label: s.label,
        original: text.slice(s.start, s.end),
        start: s.start,
        end: s.end,
        confidence: s.confidence,
      })),
    };
  }

  private async runWindow(session: OrtSessionLike, window: ContentToken[], text: string): Promise<Span[]> {
    const ids = [CLS_ID, ...window.map((t) => t.id), SEP_ID];
    const n = ids.length;
    const tensor = (values: number[]) => new this.ort.Tensor("int64", BigInt64Array.from(values, BigInt), [1, n]);
    const feeds: Record<string, unknown> = {
      input_ids: tensor(ids),
      attention_mask: tensor(ids.map(() => 1)),
    };
    if (session.inputNames.includes("token_type_ids")) feeds.token_type_ids = tensor(ids.map(() => 0));
    const out = (await session.run(feeds))[session.outputNames[0]];
    const width = out.dims[out.dims.length - 1];
    const predictions: Prediction[] = window.map((t, i) => {
      const [classIndex, confidence] = argmaxSoftmax(out.data, (i + 1) * width, width);
      return { range: t.range, classIndex, confidence };
    });
    return decodeBioes(predictions, this.labels, text);
  }

  dispose(): void {
    const session = this.session;
    this.session = null;
    if (session) void session.release().catch(() => {});
  }
}

/** Loads MaskerMini using PI_PII_REDACT_MASKER_VARIANT / PI_PII_REDACT_MASKER_DIR. */
export async function loadMaskerMiniFromEnv(): Promise<MaskerMini> {
  return MaskerMini.load({
    variant: parseVariant(process.env.PI_PII_REDACT_MASKER_VARIANT),
    directory: process.env.PI_PII_REDACT_MASKER_DIR || undefined,
  });
}
import { createHash } from "node:crypto";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { Readable } from "node:stream";
import { pipeline } from "node:stream/promises";

/** Pinned revision of https://huggingface.co/divergentlabs/masker-mini (Apache-2.0). */
export const MASKER_REVISION = "beb7235d454aa4488b6ee1cd47f417caa12a6d15";
const BASE_URL = "https://huggingface.co/divergentlabs/masker-mini/resolve";

export type MaskerVariant = "int4" | "fp16";

export const MASKER_SHA256: Record<string, string> = {
  "config.json": "d1ec3865c686b5838ff9ffcc631bfc6794b5488d30c21c1a798cd1d4f9f26688",
  "tokenizer.json": "REDACTED",
  "tokenizer_config.json": "REDACTED",
  "onnx/model_int4.onnx": "338b7c2daf15168441a93c175b1fe6b364fef9a6ef7dee65e00c9159a76fdfae",
  "onnx/model_fp16.onnx": "594dada59d570cb2fccc18fc1caa79b9a05c349ddd40e425badc2422b9ff3faf",
};

export interface MaskerFiles {
  directory: string;
  modelPath: string;
  configPath: string;
  tokenizerPath: string;
  tokenizerConfigPath: string;
}

export interface ResolveOptions {
  variant?: MaskerVariant;
  /** Use files from this directory (same layout as the HF repo); never downloads. */
  directory?: string;
  /** Override the cache root (default: $XDG_CACHE_HOME or ~/.cache). */
  cacheRoot?: string;
  /** Override fetch (tests). */
  fetchImpl?: typeof fetch;
  /** Override pinned hashes (tests). */
  hashes?: Record<string, string>;
}

export function parseVariant(value: string | undefined): MaskerVariant {
  if (value === undefined || value === "" || value === "int4") return "int4";
  if (value === "fp16") return "fp16";
  throw new Error(`Unknown PI_PII_REDACT_MASKER_VARIANT "${value}" (expected "int4" or "fp16")`);
}

async function sha256File(file: string): Promise<string> {
  const hash = createHash("sha256");
  await pipeline(fs.createReadStream(file), hash);
  return hash.digest("hex");
}

/** Throws when the file's SHA-256 differs from `expected`. */
export async function verifyFile(file: string, expected: string): Promise<void> {
  const actual = await sha256File(file);
  if (actual !== expected) {
    throw new Error(`masker-mini: SHA-256 mismatch for ${file} (expected ${expected}, got ${actual})`);
  }
}

function cacheDirectory(cacheRoot?: string): string {
  const root = cacheRoot ?? process.env.XDG_CACHE_HOME ?? path.join(os.homedir(), ".cache");
  return path.join(root, "pi-pii-redact", "masker-mini", MASKER_REVISION);
}

async function download(rel: string, dest: string, expected: string, fetchImpl: typeof fetch): Promise<void> {
  const url = `${BASE_URL}/${MASKER_REVISION}/${rel}`;
  const res = await fetchImpl(url);
  if (!res.ok || !res.body) {
    throw new Error(`masker-mini: download failed for ${url} (HTTP ${res.status})`);
  }
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  const tmp = `${dest}.${process.pid}.${Date.now()}.tmp`;
  try {
    await pipeline(Readable.fromWeb(res.body as never), fs.createWriteStream(tmp));
    await verifyFile(tmp, expected);
    fs.renameSync(tmp, dest);
  } catch (error) {
    fs.rmSync(tmp, { force: true });
    throw error;
  }
}

/**
 * Resolves (and downloads if needed) the files for the chosen variant and
 * verifies their SHA-256. User-supplied directories are verified but never modified.
 */
export async function resolveMaskerFiles(opts: ResolveOptions = {}): Promise<MaskerFiles> {
  const variant = opts.variant ?? "int4";
  const hashes = opts.hashes ?? MASKER_SHA256;
  const fetchImpl = opts.fetchImpl ?? fetch;
  const needed = ["config.json", "tokenizer.json", "tokenizer_config.json", `onnx/model_${variant}.onnx`];
  const directory = opts.directory ?? cacheDirectory(opts.cacheRoot);

  for (const rel of needed) {
    const file = path.join(directory, rel);
    const expected = hashes[rel];
    if (!expected) throw new Error(`masker-mini: no pinned hash for ${rel}`);
    if (opts.directory) {
      if (!fs.existsSync(file)) throw new Error(`masker-mini: missing ${file}`);
      await verifyFile(file, expected);
      continue;
    }
    if (fs.existsSync(file)) {
      try {
        await verifyFile(file, expected);
        continue;
      } catch {
        fs.rmSync(file, { force: true }); // corrupt cache entry: fetch it again
      }
    }
    await download(rel, file, expected, fetchImpl);
  }

  return {
    directory,
    modelPath: path.join(directory, `onnx/model_${variant}.onnx`),
    configPath: path.join(directory, "config.json"),
    tokenizerPath: path.join(directory, "tokenizer.json"),
    tokenizerConfigPath: path.join(directory, "tokenizer_config.json"),
  };
}
/** One detection returned by an NER backend. Offsets index into the input text. */
export interface NerItem {
  label: string;
  original: string;
  start: number;
  end: number;
  confidence: number;
}

/**
 * The minimal engine surface RedactorService consumes. The native `Redact`
 * instance from `@desert-ant-labs/redact` satisfies it structurally.
 */
export interface NerEngine {
  redaction(
    text: string,
    options?: { labels?: Iterable<string>; minimumConfidence?: number }
  ): Promise<{ items: NerItem[] }>;
  dispose(): void;
}
import type { Span } from "./decode.js";

/** Keeps spans whose label is requested and whose confidence reaches the threshold. */
export function filterSpans(
  spans: readonly Span[],
  labels: Iterable<string> | undefined,
  minimumConfidence: number
): Span[] {
  if (!labels) return [];
  const wanted = new Set(labels);
  if (wanted.size === 0) return [];
  return spans.filter((s) => wanted.has(s.label) && s.confidence >= minimumConfidence);
}

/**
 * Removes overlapping spans (e.g. the same entity seen in two windows), preferring
 * higher confidence, then longer spans. Returns spans sorted by start.
 */
export function dedupeSpans(spans: readonly Span[]): Span[] {
  const ranked = spans
    .slice()
    .sort((a, b) => b.confidence - a.confidence || b.end - b.start - (a.end - a.start) || a.start - b.start);
  const kept: Span[] = [];
  for (const s of ranked) {
    if (!kept.some((k) => s.start < k.end && k.start < s.end)) kept.push(s);
  }
  return kept.sort((a, b) => a.start - b.start || a.end - b.end);
}
import type { Range } from "./tokenize.js";

export interface Prediction {
  range: Range | null;
  classIndex: number;
  /** Softmax probability of the argmax class. */
  confidence: number;
}

export interface Span {
  label: string;
  start: number;
  end: number;
  confidence: number;
}

export type Prefix = "B" | "I" | "E" | "S";
export interface DecodedLabel {
  prefix: Prefix;
  type: string;
}

/** Parses `id2label` ("O", "B-CITY", ...) into a per-index table; "O"/unknown become null. */
export function buildLabelTable(id2label: Record<string, string>): Array<DecodedLabel | null> {
  const table: Array<DecodedLabel | null> = [];
  for (const [key, name] of Object.entries(id2label)) {
    const m = /^([BIES])-(.+)$/.exec(name);
    table[Number(key)] = m ? { prefix: m[1] as Prefix, type: m[2] } : null;
  }
  return table;
}

/** BIOES decode with lenient recovery, per BIOESDecoder.swift. Whitespace is trimmed from span edges. */
export function decodeBioes(
  predictions: readonly Prediction[],
  labels: ReadonlyArray<DecodedLabel | null>,
  original: string
): Span[] {
  const result: Span[] = [];
  let type: string | null = null;
  let tokens: Array<{ range: Range | null; confidence: number }> = [];

  const flush = () => {
    const t = type;
    const toks = tokens;
    type = null;
    tokens = [];
    if (t === null || toks.length === 0) return;
    const ranges = toks.flatMap((x) => (x.range ? [x.range] : []));
    if (ranges.length === 0) return;
    let start = Math.min(...ranges.map((r) => r[0]));
    let end = Math.max(...ranges.map((r) => r[1]));
    while (start < end && /\s/.test(original[start])) start++;
    while (end > start && /\s/.test(original[end - 1])) end--;
    if (start >= end) return;
    const confidence = toks.reduce((a, x) => a + x.confidence, 0) / toks.length;
    result.push({ label: t, start, end, confidence });
  };

  for (const p of predictions) {
    const lab = labels[p.classIndex] ?? null;
    if (!lab) {
      flush();
      continue;
    }
    const continues = type === lab.type && (lab.prefix === "I" || lab.prefix === "E");
    if (continues) {
      tokens.push(p);
      if (lab.prefix === "E") flush();
    } else {
      flush();
      type = lab.type;
      tokens = [p];
      if (lab.prefix === "S" || lab.prefix === "E") flush();
    }
  }
  flush();
  return result;
}

import type { LoadOptions, RedactLabel } from "@desert-ant-labs/redact/native";
import { Redact as NativeRedact } from "@desert-ant-labs/redact/native";
import type { PiiCategory, PiiRule, RedactionDetail, RedactionResult, RedactorConfig } from "../types.js";
import type { NerEngine } from "./ner-engine.js";
import { PiiVault, type VaultEntry } from "./vault.js";
import { withSilencedNativeStderr } from "./native-stderr.js";
import { defaultRules, findRuleByIdOrLabel, RULE_ID_TO_LABEL } from "../rules/default-rules.js";

/** Configuration options for RedactorService initialization. */
export interface RedactorServiceOptions {
  /** Optional options passed to Redact.load(...) (e.g. offline directory or cacheRoot). */
  loadOptions?: LoadOptions;
  /** Optional pre-instantiated or mock Redact engine (useful for unit testing). */
  redactInstance?: NerEngine;
}

/** Escapes special regular expression characters in a string. */
function escapeRegex(str: string): string {
  return str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/**
 * Constructs a safe regex matching discrete word occurrences of an entity,
 * respecting Unicode word boundaries to prevent substring mutilation of regular words
 * (e.g. preventing 'Dan' from matching inside 'Danger' or 'Rob' inside 'problem').
 */
function createEntityWordBoundaryRegex(original: string): RegExp {
  const escaped = escapeRegex(original);
  const leading = /^\w/.test(original)
    ? "\\b"
    : /^[\p{L}\p{N}_]/u.test(original)
      ? "(?<![\\p{L}\\p{N}_])"
      : "(?<!\\S)";
  const trailing = /\w$/.test(original)
    ? "\\b"
    : /[\p{L}\p{N}_]$/u.test(original)
      ? "(?![\\p{L}\\p{N}_])"
      : "(?!\\S)";
  const flags =
    /[\p{L}\p{N}]/u.test(original) && !/^[\x00-\x7F]+$/.test(original)
      ? "gu"
      : "g";
  return new RegExp(`${leading}${escaped}${trailing}`, flags);
}

/**
 * Open-vocabulary linguistic labels susceptible to false-positive classification on common English words.
 * Calibrated with a higher confidence threshold (default 0.85) to eliminate non-PII false positives.
 */
const OPEN_VOCABULARY_LABELS = new Set<string>([
  "GIVEN_NAME",
  "SURNAME",
  "STREET_NAME",
  "CITY",
  "STATE",
  "BUILDING_NUMBER",
  "SECONDARY_ADDRESS",
  "ORG",
  "URL",
]);

/** Maximum number of cached redaction results (LRU). */
const RESULT_CACHE_LIMIT = 500;

interface CachedResult {
  text: string;
  redactions: RedactionDetail[];
}

export class RedactorService {
  private rules: Map<string, PiiRule>;
  private config: RedactorConfig;
  private loadOptions?: LoadOptions;
  private instance: NerEngine | null = null;
  private initPromise: Promise<NerEngine> | null = null;
  private vault: PiiVault = new PiiVault();
  private cache: Map<string, CachedResult> = new Map();
  private cacheSig = "";

  constructor(
    customRules: PiiRule[] = [],
    initialConfig?: Partial<RedactorConfig>,
    options?: RedactorServiceOptions | LoadOptions
  ) {
    this.rules = new Map();
    for (const rule of [...defaultRules, ...customRules]) {
      this.rules.set(rule.id, { ...rule });
    }

    this.config = {
      enabled: true,
      maskUserInputs: true,
      maskToolResults: true,
      maskContextMessages: true,
      notifyOnRedact: true,
      minimumConfidence: 0.85,
      ...initialConfig,
    };

    if (options) {
      if ("redactInstance" in options || "loadOptions" in options) {
        const svcOpts = options as RedactorServiceOptions;
        this.loadOptions = svcOpts.loadOptions;
        if (svcOpts.redactInstance) {
          this.instance = svcOpts.redactInstance;
        }
      } else {
        this.loadOptions = options as LoadOptions;
      }
    }
  }

  /** Returns whether redaction is globally enabled. */
  public isEnabled(): boolean {
    return this.config.enabled;
  }

  /** Globally enable or disable redaction. */
  public setEnabled(enabled: boolean): void {
    this.config.enabled = enabled;
    this.cache.clear();
  }

  /** Returns read-only view of redactor configuration. */
  public getConfig(): Readonly<RedactorConfig> {
    return this.config;
  }

  /** Returns all registered rules (both native model labels and overlay rules). */
  public getRules(): PiiRule[] {
    return Array.from(this.rules.values());
  }

  /**
   * Toggles an individual rule by id (case, format, and alias insensitive).
   * Returns the new enabled state, or false if the rule was not found.
   */
  public toggleRule(ruleId: string, enabled?: boolean): boolean {
    const rule =
      this.rules.get(ruleId) ??
      findRuleByIdOrLabel(this.rules.values(), ruleId);

    if (!rule) return false;
    rule.enabled = enabled ?? !rule.enabled;
    this.cache.clear();
    return rule.enabled;
  }

  /**
   * Returns the initialized native Redact instance, loading it on demand if necessary.
   * Concurrent calls await the same initialization promise.
   */
  public async getRedactInstance(): Promise<NerEngine> {
    if (this.instance) {
      return this.instance;
    }
    if (!this.initPromise) {
      this.initPromise = (async () => {
        try {
          const backend = process.env.PI_PII_REDACT_BACKEND || "desert-ant";
          if (backend === "masker-mini") {
            // Experimental opt-in backend; loaded lazily so the default path never touches it.
            const { loadMaskerMiniFromEnv } = await import("./masker-mini/index.js");
            const loaded = await loadMaskerMiniFromEnv();
            try {
              await loaded.redaction("warm up", { labels: ["GIVEN_NAME"] });
            } catch (error) {
              loaded.dispose();
              throw error;
            }
            this.instance = loaded;
            return loaded;
          }
          if (backend !== "desert-ant") {
            throw new Error(
              `Unknown PI_PII_REDACT_BACKEND "${backend}" (expected "desert-ant" or "masker-mini")`
            );
          }
          const loadOpts = {
            ...this.loadOptions,
            ...(this.config.modelDirectory && !this.loadOptions?.directory
              ? { directory: this.config.modelDirectory }
              : {}),
          };
          // LiteRT logs its engine setup to fd 2 on the first inference, which
          // corrupts Pi's TUI. Load and warm up the model with that output muted.
          const inst = await withSilencedNativeStderr(async () => {
            const loaded = await NativeRedact.load(
              Object.keys(loadOpts).length > 0 ? loadOpts : undefined
            );
            try {
              await loaded.redaction("warm up");
            } catch (error) {
              loaded.dispose();
              throw error;
            }
            return loaded;
          });
          this.instance = inst;
          return inst;
        } catch (error) {
          this.initPromise = null;
          throw error;
        }
      })();
    }
    return this.initPromise;
  }

  /** Eagerly initializes the native model. */
  public async init(): Promise<void> {
    await this.getRedactInstance();
  }

  /** Releases native engine resources. Safe to call multiple times. */
  public dispose(): void {
    if (this.instance) {
      this.instance.dispose();
      this.instance = null;
    }
    this.initPromise = null;
    // The vault is intentionally kept: the session still needs it for restore.
    this.cache.clear();
  }

  /** Returns the session vault that owns all token <-> original mappings. */
  public getVault(): PiiVault {
    return this.vault;
  }

  /** Replaces the session vault (e.g. one rebuilt from persisted session entries). */
  public setVault(vault: PiiVault): void {
    this.vault = vault;
    this.cache.clear();
  }

  /**
   * Restores vault tokens in text (e.g. an LLM response) back to their original sensitive values.
   * Tolerant of dropped brackets, case changes, and inner whitespace.
   */
  public restore(processed: string, onHit?: (entry: VaultEntry) => void): string {
    return this.vault.restore(processed, onHit);
  }

  /**
   * Replaces regex matches in `text` while never touching matches that overlap a vault token.
   * `fn` returns the replacement, or null to keep the match unchanged.
   */
  private replaceOutsideTokens(
    text: string,
    regex: RegExp,
    fn: (match: string, start: number, end: number) => string | null
  ): string {
    const spans = this.vault.findTokens(text);
    let out = "";
    let last = 0;
    regex.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = regex.exec(text)) !== null) {
      const start = m.index;
      const end = start + m[0].length;
      if (m[0].length === 0) {
        regex.lastIndex++;
        continue;
      }
      if (spans.some((s) => start < s.end && end > s.start)) {
        regex.lastIndex = start + 1;
        continue;
      }
      const rep = fn(m[0], start, end);
      if (rep === null) continue;
      out += text.slice(last, start) + rep;
      last = end;
    }
    return out + text.slice(last);
  }

  private cacheSignature(): string {
    return `${this.config.minimumConfidence ?? ""}|${this.config.modelDirectory ?? ""}`;
  }

  private cacheGet(text: string): CachedResult | undefined {
    if (this.cacheSig !== this.cacheSignature()) {
      this.cache.clear();
      return undefined;
    }
    const hit = this.cache.get(text);
    if (hit) {
      this.cache.delete(text);
      this.cache.set(text, hit); // refresh LRU position
    }
    return hit;
  }

  private cacheSet(text: string, value: CachedResult): void {
    this.cacheSig = this.cacheSignature();
    this.cache.set(text, value);
    if (this.cache.size > RESULT_CACHE_LIMIT) {
      const oldest = this.cache.keys().next().value;
      if (oldest !== undefined) this.cache.delete(oldest);
    }
  }

  private buildResult(text: string, redactions: RedactionDetail[]): RedactionResult {
    return {
      text,
      hasRedactions: redactions.length > 0,
      count: redactions.length,
      redactions,
      restore: (p: string) => this.vault.restore(p),
    };
  }

  /**
   * Asynchronously redacts sensitive data (PII and API secrets) from the input text.
   * Originals are mapped to stable session-wide vault tokens, so the same value always
   * receives the same token across calls.
   */
  public async redact(text: string): Promise<RedactionResult> {
    if (!this.config.enabled || !text || typeof text !== "string") {
      return {
        text: text ?? "",
        hasRedactions: false,
        count: 0,
        redactions: [],
        restore: (p: string) => p ?? "",
      };
    }

    const vault = this.vault;
    let currentText = text;
    const allRedactions: RedactionDetail[] = [];

    // 1. Partition active rules into regex overlay rules vs native model labels
    const activeRegexRules: PiiRule[] = [];
    const activeNativeLabels: RedactLabel[] = [];
    const enabledVaultLabels = new Set<string>();

    for (const rule of this.rules.values()) {
      if (!rule.enabled) continue;

      if (rule.pattern) {
        activeRegexRules.push(rule);
        if (!rule.mask) enabledVaultLabels.add(this.overlayLabel(rule));
      } else {
        const label =
          rule.nativeLabel ??
          RULE_ID_TO_LABEL[rule.id] ??
          (rule.id.toUpperCase().replace(/-/g, "_") as RedactLabel);
        if (label) {
          activeNativeLabels.push(label);
          enabledVaultLabels.add(label);
        }
      }
    }

    // Cache hit: the cached text may predate originals the vault learned since, so re-apply
    // the (model-free) fast path before returning it.
    const cached = this.cacheGet(text);
    if (cached) {
      const redactions = cached.redactions.map((r) => ({ ...r }));
      const before = redactions.length;
      const refreshed = this.applyKnownOriginals(cached.text, enabledVaultLabels, redactions);
      if (redactions.length > before) {
        this.cacheSet(text, { text: refreshed, redactions: redactions.map((r) => ({ ...r })) });
      }
      return this.buildResult(refreshed, redactions);
    }

    // 2. Fast path: replace already-known originals with their tokens (longest first)
    currentText = this.applyKnownOriginals(currentText, enabledVaultLabels, allRedactions);

    // 3. Overlay regex rules (API keys, IP addresses, emails, custom secrets)
    for (const rule of activeRegexRules) {
      const flags = rule.pattern!.flags.includes("g")
        ? rule.pattern!.flags
        : `${rule.pattern!.flags}g`;
      const regex = new RegExp(rule.pattern!.source, flags);

      const source = currentText;
      currentText = this.replaceOutsideTokens(currentText, regex, (match, start, end) => {
        if (rule.validate && !rule.validate(match, { text: source, start, end })) return null;
        // Rules with a custom mask are one-way and never enter the vault.
        const masked = rule.mask
          ? rule.mask(match)
          : vault.tokenFor(this.overlayLabel(rule), match);
        allRedactions.push({
          category: rule.category,
          ruleId: rule.id,
          original: match,
          masked,
          placeholder: masked,
        });
        return masked;
      });
    }

    // 4. Native ML inference if any native labels are active
    // CRITICAL: If activeNativeLabels is empty, do NOT pass { labels: [] }, as
    // @desert-ant-labs/redact treats an empty array as ALL labels enabled.
    if (activeNativeLabels.length > 0) {
      const redactInstance = await this.getRedactInstance();
      const openLabels = activeNativeLabels.filter((l) => OPEN_VOCABULARY_LABELS.has(l));
      const structLabels = activeNativeLabels.filter((l) => !OPEN_VOCABULARY_LABELS.has(l));

      const nativePasses: Array<{
        labels: RedactLabel[];
        confidence: number;
      }> = [];

      // Only run structured pass if text contains digit patterns that could form numbers
      let digitProbe = currentText;
      for (const span of [...vault.findTokens(currentText)].reverse()) {
        digitProbe = digitProbe.slice(0, span.start) + digitProbe.slice(span.end);
      }
      const hasDigitSequences = /\d{2,}/.test(digitProbe.replace(/\[[A-Z0-9_]+\]/g, ""));
      if (structLabels.length > 0 && hasDigitSequences) {
        nativePasses.push({
          labels: structLabels,
          confidence: Math.min(this.config.minimumConfidence ?? 0.85, 0.60),
        });
      }
      if (openLabels.length > 0) {
        nativePasses.push({
          labels: openLabels,
          confidence: this.config.minimumConfidence ?? 0.85,
        });
      }

      for (const pass of nativePasses) {
        const source = currentText;
        const protectedSpans = vault.findTokens(source);
        const passResult = await redactInstance.redaction(source, {
          labels: pass.labels,
          minimumConfidence: pass.confidence,
        });

        // Rebuild the text from item offsets so native placeholders are replaced by vault
        // tokens and items overlapping existing tokens are dropped.
        let rebuilt = "";
        let cursor = 0;
        const accepted: Array<{ original: string; token: string }> = [];
        const items = [...passResult.items].sort(
          (a, b) => (a.start ?? 0) - (b.start ?? 0)
        );
        for (const item of items) {
          if (!item.original) continue;
          let start = item.start;
          let end = item.end;
          if (
            typeof start !== "number" ||
            typeof end !== "number" ||
            source.slice(start, end) !== item.original
          ) {
            start = source.indexOf(item.original, cursor);
            end = start + item.original.length;
          }
          if (start < cursor) continue; // overlaps a previous item or is unlocatable
          if (protectedSpans.some((s) => start < s.end && end > s.start)) continue;

          const token = vault.tokenFor(item.label, item.original);
          const matchingRule = this.findRuleForNativeLabel(item.label);
          rebuilt += source.slice(cursor, start) + token;
          cursor = end;
          accepted.push({ original: item.original, token });
          allRedactions.push({
            category: matchingRule?.category ?? this.mapNativeLabelToCategory(item.label),
            ruleId: matchingRule?.id ?? item.label.toLowerCase(),
            original: item.original,
            masked: token,
            placeholder: token,
            confidence: item.confidence,
            start,
            end,
          });
        }
        currentText = rebuilt + source.slice(cursor);

        // Sanitize repeated discrete occurrences of detected entities with the same token
        // (no extra RedactionDetail entries: each occurrence is reported once at detection).
        for (const { original, token } of accepted) {
          if (original.trim().length <= 1) continue;
          currentText = this.replaceOutsideTokens(
            currentText,
            createEntityWordBoundaryRegex(original),
            () => token
          );
        }
      }
    }

    this.cacheSet(text, {
      text: currentText,
      redactions: allRedactions.map((r) => ({ ...r })),
    });
    return this.buildResult(currentText, allRedactions);
  }

  /** Replaces already-known vault originals (for enabled labels) with their tokens, longest first. */
  private applyKnownOriginals(
    text: string,
    enabledVaultLabels: ReadonlySet<string>,
    redactions: RedactionDetail[]
  ): string {
    let currentText = text;
    for (const entry of this.vault.knownOriginals()) {
      if (!enabledVaultLabels.has(entry.label)) continue;
      if (entry.original.trim().length <= 1 || !currentText.includes(entry.original)) continue;
      const rule = this.findRuleForNativeLabel(entry.label);
      currentText = this.replaceOutsideTokens(
        currentText,
        createEntityWordBoundaryRegex(entry.original),
        () => {
          redactions.push({
            category: rule?.category ?? this.mapNativeLabelToCategory(entry.label),
            ruleId: rule?.id ?? entry.label.toLowerCase(),
            original: entry.original,
            masked: entry.token,
            placeholder: entry.token,
          });
          return entry.token;
        }
      );
    }
    return currentText;
  }

  private overlayLabel(rule: PiiRule): string {
    return (
      rule.nativeLabel ??
      (rule.category === "api-key"
        ? "API_KEY"
        : rule.category.toUpperCase().replace(/[-\s]/g, "_"))
    );
  }

  private findRuleForNativeLabel(label: string): PiiRule | undefined {
    return findRuleByIdOrLabel(this.rules.values(), label);
  }

  private mapNativeLabelToCategory(label: string): PiiCategory {
    const upper = label.toUpperCase();
    switch (upper) {
      case "EMAIL":
        return "email";
      case "PHONE":
        return "phone";
      case "IP_ADDRESS":
        return "ip";
      case "CREDIT_CARD":
        return "credit-card";
      default:
        return upper as PiiCategory;
    }
  }
}

import fs from "node:fs";
import type { NerEngine, NerItem } from "../ner-engine.js";
import { chunkWindows } from "./chunk.js";
import { buildLabelTable, decodeBioes, type DecodedLabel, type Prediction, type Span } from "./decode.js";
import { dedupeSpans, filterSpans } from "./merge.js";
import { parseVariant, resolveMaskerFiles, type MaskerVariant } from "./model-files.js";
import { tokenizeWithOffsets, type ContentToken, type TokenizerLike } from "./tokenize.js";

const CLS_ID = 1;
const SEP_ID = 2;

export interface MaskerLoadOptions {
  variant?: MaskerVariant;
  directory?: string;
}

/** Minimal views of the onnxruntime-node API we use. */
interface OrtTensorLike {
  dims: readonly number[];
  data: ArrayLike<number | bigint>;
}
interface OrtSessionLike {
  inputNames: readonly string[];
  outputNames: readonly string[];
  run(feeds: Record<string, unknown>): Promise<Record<string, OrtTensorLike>>;
  release(): Promise<void>;
}
interface OrtLike {
  Tensor: new (type: "int64", data: BigInt64Array, dims: number[]) => unknown;
  InferenceSession: {
    create(path: string, options?: Record<string, unknown>): Promise<OrtSessionLike>;
  };
}

async function importOptional<T>(name: string): Promise<T> {
  try {
    const mod = (await import(name)) as { default?: unknown };
    return ((mod as Record<string, unknown>).InferenceSession || !mod.default ? mod : mod.default) as T;
  } catch (error) {
    throw new Error(
      `masker-mini backend needs the optional packages "onnxruntime-node" and "@huggingface/tokenizers" ` +
        `(install them with: npm install onnxruntime-node @huggingface/tokenizers): ${(error as Error).message}`
    );
  }
}

/** Softmax over one row of logits; returns [argmax, probability of argmax]. */
export function argmaxSoftmax(logits: ArrayLike<number | bigint>, offset: number, width: number): [number, number] {
  let max = -Infinity;
  let arg = 0;
  for (let i = 0; i < width; i++) {
    const v = Number(logits[offset + i]);
    if (v > max) {
      max = v;
      arg = i;
    }
  }
  let sum = 0;
  for (let i = 0; i < width; i++) sum += Math.exp(Number(logits[offset + i]) - max);
  return [arg, 1 / sum];
}

export class MaskerMini implements NerEngine {
  private session: OrtSessionLike | null;
  private readonly ort: OrtLike;
  private readonly tokenizer: TokenizerLike;
  private readonly labels: Array<DecodedLabel | null>;

  // No parameter properties: the package ships .ts source, which must stay strip-only compatible.
  private constructor(
    session: OrtSessionLike,
    ort: OrtLike,
    tokenizer: TokenizerLike,
    labels: Array<DecodedLabel | null>
  ) {
    this.session = session;
    this.ort = ort;
    this.tokenizer = tokenizer;
    this.labels = labels;
  }

  static async load(opts: MaskerLoadOptions = {}): Promise<MaskerMini> {
    const files = await resolveMaskerFiles({ variant: opts.variant, directory: opts.directory });
    const ort = await importOptional<OrtLike>("onnxruntime-node");
    const { Tokenizer } = await importOptional<{
      Tokenizer: new (json: unknown, config: unknown) => TokenizerLike;
    }>("@huggingface/tokenizers");
    const readJson = (p: string) => JSON.parse(fs.readFileSync(p, "utf8"));
    const tokenizer = new Tokenizer(readJson(files.tokenizerPath), readJson(files.tokenizerConfigPath));
    const labels = buildLabelTable(readJson(files.configPath).id2label);
    // logSeverityLevel 3 = errors only, so ORT warnings do not land in Pi's TUI.
    const session = await ort.InferenceSession.create(files.modelPath, { logSeverityLevel: 3 });
    return new MaskerMini(session, ort, tokenizer, labels);
  }

  async redaction(
    text: string,
    options: { labels?: Iterable<string>; minimumConfidence?: number } = {}
  ): Promise<{ items: NerItem[] }> {
    const session = this.session;
    if (!session) throw new Error("masker-mini: model has been disposed");
    if (!options.labels || !text.trim()) return { items: [] };

    const tokens = tokenizeWithOffsets(this.tokenizer, text);
    const spans: Span[] = [];
    for (const window of chunkWindows(tokens)) {
      spans.push(...(await this.runWindow(session, window, text)));
    }
    const kept = dedupeSpans(filterSpans(spans, options.labels, options.minimumConfidence ?? 0));
    return {
      items: kept.map((s) => ({
        label: s.label,
        original: text.slice(s.start, s.end),
        start: s.start,
        end: s.end,
        confidence: s.confidence,
      })),
    };
  }

  private async runWindow(session: OrtSessionLike, window: ContentToken[], text: string): Promise<Span[]> {
    const ids = [CLS_ID, ...window.map((t) => t.id), SEP_ID];
    const n = ids.length;
    const tensor = (values: number[]) => new this.ort.Tensor("int64", BigInt64Array.from(values, BigInt), [1, n]);
    const feeds: Record<string, unknown> = {
      input_ids: tensor(ids),
      attention_mask: tensor(ids.map(() => 1)),
    };
    if (session.inputNames.includes("token_type_ids")) feeds.token_type_ids = tensor(ids.map(() => 0));
    const out = (await session.run(feeds))[session.outputNames[0]];
    const width = out.dims[out.dims.length - 1];
    const predictions: Prediction[] = window.map((t, i) => {
      const [classIndex, confidence] = argmaxSoftmax(out.data, (i + 1) * width, width);
      return { range: t.range, classIndex, confidence };
    });
    return decodeBioes(predictions, this.labels, text);
  }

  dispose(): void {
    const session = this.session;
    this.session = null;
    if (session) void session.release().catch(() => {});
  }
}

/** Loads MaskerMini using PI_PII_REDACT_MASKER_VARIANT / PI_PII_REDACT_MASKER_DIR. */
export async function loadMaskerMiniFromEnv(): Promise<MaskerMini> {
  return MaskerMini.load({
    variant: parseVariant(process.env.PI_PII_REDACT_MASKER_VARIANT),
    directory: process.env.PI_PII_REDACT_MASKER_DIR || undefined,
  });
}
