// Loading the on-device model dominates per-test cost, and most tests create a fresh
// RedactorService. Load once per worker and hand the same instance to every service;
// dispose() is a no-op so one test cannot tear the model down for the next.
export const realLoad = Redact.load.bind(Redact);
const loaded = new Map<string, Promise<Redact>>();

vi.spyOn(Redact, "load").mockImplementation((options?: Parameters<typeof Redact.load>[0]) => {
  const key = JSON.stringify(options ?? {});
  let p = loaded.get(key);
  if (!p) {
    p = realLoad(options).then((inst) => {
      inst.dispose = () => {};
      return inst;
    });
    p.catch(() => loaded.delete(key));
    loaded.set(key, p);
  }
  return p;
});

// Experimental backend: share one masker-mini load per worker the same way.
if (process.env.PI_PII_REDACT_BACKEND === "masker-mini") {
  const { MaskerMini } = await import("../src/services/masker-mini/index.js");
  const realMaskerLoad = MaskerMini.load.bind(MaskerMini);
  const maskerLoaded = new Map<string, Promise<InstanceType<typeof MaskerMini>>>();

  vi.spyOn(MaskerMini, "load").mockImplementation((options?: Parameters<typeof MaskerMini.load>[0]) => {
    const key = JSON.stringify(options ?? {});
    let p = maskerLoaded.get(key);
    if (!p) {
      p = realMaskerLoad(options).then((inst) => {
        inst.dispose = () => {};
        return inst;
      });
      p.catch(() => maskerLoaded.delete(key));
      maskerLoaded.set(key, p);
    }
    return p;
