s=open(p).read()
s=s.replace('import { parseVariant, resolveMaskerFiles }','import { resolveMaskerFiles }')
s=s.replace('import { RedactorService } from "../../src/services/redactor.js";\n','import { refineSpans } from "../../src/services/masker-mini/postprocess.js";\n')
